from datetime import date, timedelta

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    y, m, d = (int(p) for p in start.split("-"))
    cur = date(y, m, d)
    parts = rule.split(" ")
    kind = parts[0]
    k = int(parts[1])
    out: list[str] = []

    if kind == "DAILY":
        dt = cur
        for _ in range(count):
            out.append(dt.isoformat())
            dt += timedelta(days=k)
        return out

    if kind == "WEEKLY":
        days = sorted(_WD[c] for c in parts[2].split(","))
        monday = cur - timedelta(days=cur.weekday())
        w = 0
        while len(out) < count:
            base = monday + timedelta(days=7 * w)
            for wd in days:
                dt = base + timedelta(days=wd)
                if dt >= cur:
                    out.append(dt.isoformat())
                    if len(out) == count:
                        break
            w += k
        return out

    def add_months(i: int) -> tuple[int, int]:
        yy = cur.year + (cur.month - 1 + i) // 12
        mm = (cur.month - 1 + i) % 12 + 1
        return yy, mm

    def last_of_month(yy: int, mm: int) -> date:
        if mm == 12:
            return date(yy + 1, 1, 1) - timedelta(days=1)
        return date(yy, mm + 1, 1) - timedelta(days=1)

    if kind == "MONTHLY" and len(parts) == 3:
        dom = int(parts[2])
        mi = 0
        while len(out) < count:
            yy, mm = add_months(mi)
            if dom == -1:
                dt = last_of_month(yy, mm)
            else:
                try:
                    dt = date(yy, mm, dom)
                except ValueError:
                    dt = None
            if dt is not None and dt >= cur:
                out.append(dt.isoformat())
            mi += k
        return out

    if kind == "MONTHLY":
        n = int(parts[2])
        wd = _WD[parts[3]]
        mi = 0
        while len(out) < count:
            yy, mm = add_months(mi)
            if n == -1:
                last = last_of_month(yy, mm)
                dt = last - timedelta(days=(last.weekday() - wd) % 7)
            else:
                first = date(yy, mm, 1)
                dt = first + timedelta(days=(wd - first.weekday()) % 7 + 7 * (n - 1))
                if dt.month != mm:
                    dt = None
            if dt is not None and dt >= cur:
                out.append(dt.isoformat())
            mi += k
        return out

    mm_s, dd_s = parts[2].split("-")
    mm, dd = int(mm_s), int(dd_s)
    yi = 0
    while len(out) < count:
        try:
            dt = date(cur.year + yi, mm, dd)
        except ValueError:
            dt = None
        if dt is not None and dt >= cur:
            out.append(dt.isoformat())
        yi += k
    return out
